    // No live `patch +/-N` claim. The retired one is quoted only as history,
    // in the sentence that names it as what went wrong.
    const claims = [...amendment.matchAll(/\bpatch \+\/-(\d+)/g)].map((m) => Number(m[1]));
    for (const claim of claims) {
