// Re-runs the agent-deck-spec.md guards from src/release/readme.test.ts against
// the edited spec, without invoking vitest. Patterns copied verbatim from that file.
import { readFileSync } from 'node:fs';

const SPEC = readFileSync(process.argv[2], 'utf8');

const SUPERSEDED_PHRASES = ['pin to the installed cc version', 'no multi-version support'];

const SUPERSEDED_PATTERNS = [
  { name: 'pinned-to-installed', re: /\bpin(?:ned|ning|s)?\b[^.]{0,40}\binstalled\b/i },
  {
    name: 'no-multi-version-support',
    re: /\bno\b[^.]{0,30}\bmulti[-\s]?(?:cc[-\s]?)?version\b[^.]{0,20}\bsupport/i,
  },
  {
    name: 'single-blessed-version',
    re: /\b(?:a\s+)?single\s+(?:pinned|supported|accepted|blessed)\s+(?:cc\s+)?version\b/i,
  },
  { name: 'exactly-one-version', re: /\b(?:exactly|only)\s+one\s+(?:cc\s+|claude\s+code\s+)?version\b/i },
  { name: 'no-drift-tolerance', re: /\bno\s+drift\s+(?:tolerance|fixtures)\b/i },
  { name: 'do-not-build-drift', re: /\bdo\s+not\s+build\s+drift\b/i },
  { name: 'no-version-matrix', re: /\bno\s+version\s+matrix\b/i },
];

const MARKED_SUPERSEDED = /\bsupersed(?:e|es|ed|ing)\b/i;

function sentencesOf(text) {
  return text
    .split('\n')
    .flatMap((line) => line.split(/(?<=[.!?])\s+/))
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}

function contradictionsIn(text) {
  const found = [];
  for (const sentence of sentencesOf(text)) {
    if (MARKED_SUPERSEDED.test(sentence)) continue;
    for (const { name, re } of SUPERSEDED_PATTERNS) {
      if (re.test(sentence)) found.push(name + ': ' + sentence);
    }
  }
  return found;
}

const results = [];
const lower = SPEC.toLowerCase();
results.push([
  'no superseded phrase anywhere',
  SUPERSEDED_PHRASES.every((p) => !lower.includes(p)),
]);
const contradictions = contradictionsIn(SPEC);
results.push(['no reworded restatement, whole document', contradictions.length === 0]);
const exempted = sentencesOf(SPEC).filter(
  (s) => MARKED_SUPERSEDED.test(s) && SUPERSEDED_PATTERNS.some(({ re }) => re.test(s)),
);
results.push(['exemptions <= 3 (actual ' + exempted.length + ')', exempted.length <= 3]);

const AMENDMENT_HEADING = '## Amendment 2026-08-26 — Version posture';
const start = SPEC.indexOf(AMENDMENT_HEADING);
results.push(['version-posture heading located', start >= 0]);
const amendment = start >= 0 ? SPEC.slice(start) : '';
results.push(['heading occurs exactly once', SPEC.indexOf(AMENDMENT_HEADING) === SPEC.lastIndexOf(AMENDMENT_HEADING)]);
results.push(['version-posture amendment is the last section', !amendment.includes('\n## ')]);

const anchors = [...amendment.matchAll(/\banchor(?:ed on)?:?\s+`(\d+\.\d+\.\d+)`/gi)].map((m) => m[1]);
results.push(['anchors in slice are all 2.1.246 (' + anchors.join(',') + ')', anchors.length > 0 && anchors.every((a) => a === '2.1.246')]);
const minors = [...amendment.matchAll(/\bminor \+\/-(\d+)/g)].map((m) => Number(m[1]));
results.push(['minor claims in slice are all 1 (' + minors.join(',') + ')', minors.length > 0 && minors.every((m) => m === 1)]);
const patchClaims = [...amendment.matchAll(/\bpatch \+\/-(\d+)/g)].map((m) => Number(m[1]));
results.push([
  'patch claims in slice are history-only (' + patchClaims.join(',') + ')',
  patchClaims.every((c) => amendment.includes('box of patch +/-' + String(c))),
]);
for (const needle of ['src/parser/fingerprint.ts', 'versionChangedMidFile', '2026-08-26', '§3', 'fixtures/cc-2.1.246/', 'patch component is not compared']) {
  results.push(['slice contains ' + needle, amendment.includes(needle)]);
}

let failed = 0;
for (const [name, ok] of results) {
  if (!ok) failed += 1;
  console.log((ok ? 'PASS  ' : 'FAIL  ') + name);
}
if (contradictions.length > 0) console.log(contradictions.join('\n'));
console.log('\n' + String(results.length - failed) + ' passed, ' + String(failed) + ' failed');
process.exit(failed === 0 ? 0 : 1);
